import { StudioProApi } from "@mendix/extensions-api";
import { Agent, Variable } from "../types/agent";


export function createNewAgent(): Agent {
    return {
        modelDocumentUUID: crypto.randomUUID(),
        description: "",
        entity: "",
        systemPrompt: "",
        userPrompt: "",
        usageType: "Task",
        variables: [],
        tools: []
    };
}


export function calculateVariables(agent: Agent) {

    const systemPromptPlaceholders = agent.systemPrompt.match(/\{\{([^}]+)\}\}/g) || [];
    const userPromptPlaceholders = agent.userPrompt ? agent.userPrompt.match(/\{\{([^}]+)\}\}/g) || [] : [];

    const placeholders: string[] = [...systemPromptPlaceholders, ...userPromptPlaceholders];

    if (placeholders.length === 0) {
        return [];
    }

    // The keys are only the part between {{}}
    const variableKeys: string[] = placeholders.map(match =>
        match.replace(/\{\{|\}\}/g, '')
    );

    // Remove duplicates
    const uniqueVariableKeys: string[] = [...new Set(variableKeys)];

    // Get or create Variable objects (keep the ones that already exist on the current agent)
    const currentVariables: Variable[] = agent.variables;
    const newVariables: Variable[] = uniqueVariableKeys.map(name => {
        const existingVariable = currentVariables.find(v => v.key === name);
        return existingVariable || {
            key: name,
            isAttributeInEntity: false,
            backgroundColor: '',
            borderColor: '',
            testValue: ''
        };
    });

    // Return variables with the color code fields updated
    return setColors(newVariables);
}


export const createHighlightRules = (variables: Variable[]) => {
    return variables.map(v => ({
        pattern: new RegExp('\\{\\{' + v.key + '\\}\\}', 'g'),
        style: {
            color: v.borderColor,
            backgroundColor: v.backgroundColor,
            border: `1px solid ${v.borderColor}`,
            borderRadius: '2px',
            margin: '0 -1px'
        }
    }));
};


function setColors(variables: Variable[]): Variable[] {
    // Color set from Figma design: [BackgroundColor, BorderColor]
    const colorPalette: string[][] = [
        ['#DCEEFE', '#0123C6'], // Blue
        ['#E2E0FC', '#4701D4'], // Purple
        ['#F7E0FF', '#780194'], // Violet
        ['#FFE5E9', '#9E051B'], // Red
        ['#FFF2CF', '#803600'], // Yellow
        ['#E1FAE1', '#076407'], // Green
    ];

    return variables.map((variable, index) => ({
        ...variable,
        backgroundColor: colorPalette[index % colorPalette.length][0],
        borderColor: colorPalette[index % colorPalette.length][1]
    }));
}


export const isAgentEntityFound = async (studioPro: StudioProApi, agent: Agent) => {
    console.log(agent.entity)
    if (!agent.entity) {
        return true;
    }
    const moduleName = agent.entity.split('.')[0];
    const entityName = agent.entity.split('.')[1];
    const domainModel = await studioPro.app.model.domainModels.getDomainModel(moduleName);
    const entity = domainModel ? domainModel.entities.find(e => e.name === entityName) : null;
    console.log(entity, entity != null)
    return entity != null;
};